import XCTest

class BlueskyUITest: XCTestCase {
    let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")

    func testQuotePost() {
        app.activate()

        // Take a screenshot to see the current state
        XCTAssert(app.exists)

        // Try to find the first post and its repost button
        // The repost button should have accessibility identifier or label
        let postButtons = app.buttons.matching(NSPredicate(format: "label LIKE '*repost*' OR label LIKE '*share*'"))

        if postButtons.count > 0 {
            postButtons.element(boundBy: 0).tap()
        }
    }
}
EOF

cat > /tmp/BlueskyQuoteTest.swift << 'EOF'
import XCTest

class BlueskyQuoteTest: XCTestCase {
    func testQuotePostFirstPost() {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()

        // Give the app time to respond
        sleep(1)

        // Find all buttons in the interface
        let allButtons = app.buttons.allElementsBoundByIndex
        print("Total buttons found: \(allButtons.count)")

        // Print button labels to help us find the repost button
        for (index, button) in allButtons.enumerated().prefix(20) {
            print("Button \(index): label='\(button.label)'")
        }

        // Look for the repost button - it might have a specific accessibility label
        let buttons = app.buttons
        for button in buttons.allElementsBoundByAccessibilityElement() {
            let label = button.label
            print("Found button: \(label)")

            if label.contains("repost") || label.contains("share") || label.contains("Post") {
                print("Tapping button: \(label)")
                button.tap()
                break
            }
        }
    }
}
EOF
