import Foundation

// Try to test a Bluesky deep link format
// Common patterns might be:
// bsky://post/[cid]
// bsky://profile/[did]/post/[cid]
// bsky://quote/[cid]

let deepLinks = [
    "bsky://compose?text=sharing+this&quote=[post-uri]",
    "bsky://intent/compose?text=sharing%20this",
]

for link in deepLinks {
    print("Testing deep link: \(link)")
}

// Let's also try to understand the app structure
let appPath = "/Applications/Bluesky.app"
if FileManager.default.fileExists(atPath: appPath) {
    print("Found Bluesky app at: \(appPath)")
} else {
    print("Bluesky app not found at expected location")
}

EOF

